 canMove(){return !this.paused&&this.human()&&['aim','retreat'].includes(this.phase)&&this.active?.hp>0&&this.fuel>0}
 canFire(){return !this.paused&&this.human()&&this.phase==='aim'&&this.active?.hp>0}
 select(i){if(!this.canFire()||!WEAPONS[i]||this.ammo[this.team][i]===0)return false;this.weapon=i;this.emit('select');return true}
 setAim(angle,power){if(this.canFire()){this.angle=clamp(angle,5,175);this.power=clamp(power,1,100);this.active.face=this.angle>90?-1:1}}
 checkWin(){const a=this.alive(0).length,b=this.alive(1).length;if(a&&b)return false;this.phase='ended';this.winner=a?0:b?1:-1;this.projectile=null;this.emit('end',{winner:this.winner});return true}
 nextTurn(){if(this.checkWin())return;this.team=1-this.team;for(let n=0;n<3;n++){this.indices[this.team]=(this.indices[this.team]+1)%3;let id=this.team*3+this.indices[this.team];if(this.units[id].hp>0){this.activeId=id;break}}this.turn++;this.phase='ready';this.clock=3;this.fuel=100;this.weapon=0;this.angle=this.team?135:45;this.power=65;this.wind=Math.round((this.rng()*2-1)*30);this.input=0;this.aiWait=1.6+this.rng()*.7;this.rest=0;this.retreatClock=0;this.emit('turn',{team:this.team,id:this.activeId});if(this.turn>=21&&!this.sudden){this.sudden=true;this.emit('sudden')}}
 jump(){if(!this.canMove()||(!this.active.grounded&&this.active.coyote<=0)||this.fuel<15)return false;let u=this.active;u.vy=-247;u.vx=u.face*52;u.grounded=false;u.coyote=0;this.fuel-=15;this.emit('jump',{x:u.x,y:u.y});return true}
